using System;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Shapes;
using System.Windows.Threading;
using System.Windows.Automation;
using Forms=System.Windows.Forms;

namespace FramePilot {
 // Native WPF presentation of the shared editors. Original controls remain the
 // model for values, validation and actions; none are reparented or duplicated.
 sealed class ToolPages : ScrollViewer, IDisposable {
  readonly MainForm app;
  readonly Dictionary<string,ToolView> views=new Dictionary<string,ToolView>();
  readonly DispatcherTimer timer;
  ToolView current;
  public ToolPages(MainForm app){this.app=app;Background=Tone("#0D0B0A");VerticalScrollBarVisibility=ScrollBarVisibility.Auto;HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled;Padding=new Thickness(22,16,22,24);timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};timer.Tick+=delegate{if(IsVisible&&current!=null)current.Sync();};timer.Start();}
  public void ShowPage(string name){ToolView view;if(!views.TryGetValue(name,out view)){view=new ToolView(app,name);views.Add(name,view);}if(current!=view){current=view;Content=view;ScrollToTop();}view.Sync();}
  public void Dispose(){timer.Stop();Content=null;views.Clear();}
  internal static Brush Tone(string hex)=>CombinedStudio.ThemePalette.Brush(hex);
 }

 sealed class ToolView : StackPanel {
  readonly MainForm app;
  readonly List<Action> updates=new List<Action>();
  bool syncing;
  static readonly Brush Ink=ToolPages.Tone("#F3ECE4"),Muted=ToolPages.Tone("#A39789"),Accent=ToolPages.Tone("#E8964A"),PanelBrush=ToolPages.Tone("#1A1613"),Line=ToolPages.Tone("#2B231D"),Raised=ToolPages.Tone("#221C18");
  static readonly Dictionary<string,string> Sections=new Dictionary<string,string>{
   {"Game profiles","Profile studio"},{"Session mode","Session preferences"},{"Background apps","Apps & actions"},{"Startup apps","Startup preferences"},{"Drivers","Driver center"},{"Storage & apps","Storage center"},{"Maintenance","Maintenance workspace"},{"Diagnostics","Diagnostics workspace"},{"Compare runs","Capture comparison"},{"Recovery","Recovery center"},{"Updates & notes","Release center"},{"About & sources","About FramePilot"},{"Hardware","Hardware report"},{"Windows tuning","Windows preferences"}};
  public ToolView(MainForm app,string name){this.app=app;var source=app.WpfToolSource(name);var controls=source.Controls.Cast<Forms.Control>().ToArray();
   var heroContent=new StackPanel();heroContent.Children.Add(Text(name.ToUpperInvariant(),12,Accent));heroContent.Children.Add(new TextBlock{Text=controls[0].Text,Foreground=Ink,FontSize=30,FontWeight=FontWeights.SemiBold,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,8)});heroContent.Children.Add(Text(controls[1].Text,13,Muted));var hero=Card(heroContent);hero.Padding=new Thickness(26,22,26,24);hero.Background=new LinearGradientBrush(ToolPages.Tone("#38271B").Color(),ToolPages.Tone("#1A1613").Color(),0);Children.Add(hero);
   string section;Sections.TryGetValue(name,out section);Children.Add(new TextBlock{Text=section??name,Foreground=Ink,FontSize=18,FontWeight=FontWeights.SemiBold,Margin=new Thickness(2,4,0,14)});
   // Group adjacent options and actions into one workspace, with reports and
   // inventories in their own cards. Everything stretches with the viewport.
   StackPanel group=null;Border groupCard=null;
   foreach(var control in controls.Skip(2)){
    bool standalone=control is Forms.TextBox&&((Forms.TextBox)control).Multiline||control is Forms.ListBox||control is Forms.ListView||control is FrameChart||control is Forms.Panel&&!(control is Forms.FlowLayoutPanel);
    if(standalone){group=null;groupCard=null;var card=Card(Convert(control,false));Children.Add(card);Observe(control,card);}
    else{if(group==null){group=new StackPanel();groupCard=Card(group);Children.Add(groupCard);}var element=Convert(control,false);group.Children.Add(element);Observe(control,element);}
   }
   Sync();
  }
  static Border Card(UIElement child){return new Border{Child=child,Background=PanelBrush,BorderBrush=Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(14),Padding=new Thickness(20),Margin=new Thickness(0,0,0,14)};}
  static TextBlock Text(string value,double size,Brush brush){return new TextBlock{Text=value,FontSize=size,Foreground=brush,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,8)};}
  void Observe(Forms.Control source,FrameworkElement target){updates.Add(delegate{target.IsEnabled=source.Enabled;target.Visibility=MainForm.WpfControlVisible(source)?Visibility.Visible:Visibility.Collapsed;});AutomationProperties.SetName(target,string.IsNullOrWhiteSpace(source.AccessibleName)?source.Text:source.AccessibleName);}
  public void Sync(){if(syncing)return;syncing=true;try{foreach(var update in updates)update();}finally{syncing=false;}}
  void Write(Action action){if(syncing)return;try{action();Sync();}catch(Exception e){MessageBox.Show(Window.GetWindow(this),e.GetBaseException().Message,"FramePilot",MessageBoxButton.OK,MessageBoxImage.Information);Sync();}}
  FrameworkElement Convert(Forms.Control source,bool inline){
   FrameworkElement result;
   var button=source as Forms.Button;
   if(button!=null){var view=new Button{Content=button.Text,FontSize=12,MinHeight=38};view.Click+=delegate{Write(()=>app.WpfToolClick(button));};updates.Add(delegate{view.Content=button.Text;});result=view;}
   else if(source is Forms.CheckBox){var check=(Forms.CheckBox)source;var view=new CheckBox{Content=check.Text,Foreground=Ink,FontSize=13,Margin=new Thickness(0,5,16,10)};view.Checked+=delegate{Write(()=>check.Checked=true);};view.Unchecked+=delegate{Write(()=>check.Checked=false);};updates.Add(delegate{view.IsChecked=check.Checked;view.Content=check.Text;});result=view;}
   else if(source is Forms.ComboBox){var combo=(Forms.ComboBox)source;var view=new ComboBox{MinWidth=160,Width=Math.Min(320,Math.Max(160,combo.Width)),MinHeight=38,Margin=new Thickness(0,0,12,10)};view.SelectionChanged+=delegate{Write(()=>combo.SelectedIndex=view.SelectedIndex);};string key=null;updates.Add(delegate{string next=string.Join("\n",combo.Items.Cast<object>().Select(x=>x.ToString()));if(key!=next){key=next;view.ItemsSource=combo.Items.Cast<object>().ToArray();}view.SelectedIndex=combo.SelectedIndex;});result=view;}
   else if(source is Forms.NumericUpDown){var number=(Forms.NumericUpDown)source;var row=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,14,10)};var box=new TextBox{Width=64,MinHeight=36,Padding=new Thickness(8),VerticalContentAlignment=VerticalAlignment.Center};var down=new Button{Content="−",Padding=new Thickness(9,6,9,6),Margin=new Thickness(0,0,4,0)};var up=new Button{Content="+",Padding=new Thickness(9,6,9,6),Margin=new Thickness(4,0,0,0)};Action commit=delegate{decimal value;if(decimal.TryParse(box.Text,out value))Write(()=>number.Value=Math.Max(number.Minimum,Math.Min(number.Maximum,value)));else box.Text=number.Value.ToString();};box.LostKeyboardFocus+=delegate{commit();};box.KeyDown+=delegate(object s,System.Windows.Input.KeyEventArgs e){if(e.Key==System.Windows.Input.Key.Enter){commit();e.Handled=true;}};down.Click+=delegate{Write(()=>number.Value=Math.Max(number.Minimum,number.Value-number.Increment));};up.Click+=delegate{Write(()=>number.Value=Math.Min(number.Maximum,number.Value+number.Increment));};updates.Add(delegate{if(!box.IsKeyboardFocusWithin)box.Text=number.Value.ToString();});row.Children.Add(down);row.Children.Add(box);row.Children.Add(up);result=row;}
   else if(source is Forms.TextBox){var box=(Forms.TextBox)source;if(box.UseSystemPasswordChar){var view=new PasswordBox{Width=240,MinHeight=38,Padding=new Thickness(10),Background=Raised,Foreground=Ink,BorderBrush=Line,Margin=new Thickness(0,0,12,10)};view.PasswordChanged+=delegate{Write(()=>box.Text=view.Password);};updates.Add(delegate{if(view.Password!=box.Text)view.Password=box.Text;});result=view;}else{var view=new TextBox{Text=box.Text,IsReadOnly=box.ReadOnly,AcceptsReturn=box.Multiline,TextWrapping=box.Multiline?TextWrapping.Wrap:TextWrapping.NoWrap,VerticalScrollBarVisibility=box.Multiline?ScrollBarVisibility.Auto:ScrollBarVisibility.Hidden,MinHeight=box.Multiline?Math.Max(90,box.Height):38,MaxHeight=box.Multiline?Math.Max(120,box.Height+60):double.PositiveInfinity,Padding=new Thickness(12,9,12,9),FontSize=13,Margin=new Thickness(0,0,inline?12:0,10),VerticalContentAlignment=VerticalAlignment.Center};if(inline)view.Width=Math.Min(320,Math.Max(180,box.Width));if(box.Multiline)view.FontFamily=new FontFamily("Consolas");view.TextChanged+=delegate{if(!box.ReadOnly)Write(()=>box.Text=view.Text);};updates.Add(delegate{if(view.Text!=box.Text)view.Text=box.Text;view.IsReadOnly=box.ReadOnly;});result=view;}}
   else if(source is Forms.CheckedListBox){result=CheckedItems((Forms.CheckedListBox)source);}
   else if(source is Forms.ListBox){var list=(Forms.ListBox)source;var view=ListSurface(list.Height);string key=null;view.SelectionChanged+=delegate{Write(()=>list.SelectedIndex=view.SelectedIndex);};updates.Add(delegate{string next=string.Join("\n",list.Items.Cast<object>().Select(x=>x.ToString()));if(key!=next){key=next;view.ItemsSource=list.Items.Cast<object>().ToArray();}view.SelectedIndex=list.SelectedIndex;});result=view;}
   else if(source is Forms.ListView){result=Inventory((Forms.ListView)source);}
   else if(source is FrameChart){result=Plot((FrameChart)source);}
   else if(source is Forms.Label){var label=(Forms.Label)source;var view=Text(label.Text,label.Font.Bold?17:13,label.Font.Bold?Ink:Muted);if(inline){view.VerticalAlignment=VerticalAlignment.Center;view.Margin=new Thickness(0,8,10,10);}updates.Add(delegate{view.Text=label.Text;});result=view;}
   else if(source.HasChildren){bool horizontal=source is Forms.FlowLayoutPanel&&((Forms.FlowLayoutPanel)source).FlowDirection==Forms.FlowDirection.LeftToRight;Panel container=horizontal?(Panel)new WrapPanel():new StackPanel();var children=source.Controls.Cast<Forms.Control>();if(!(source is Forms.FlowLayoutPanel))children=children.OrderBy(x=>x.Top).ThenBy(x=>x.Left);foreach(var child in children){var element=Convert(child,horizontal);container.Children.Add(element);Observe(child,element);}result=container;}
   else {throw new InvalidOperationException("No WPF presentation for "+source.GetType().Name+" on "+app.WpfPage);}
   Observe(source,result);return result;
  }
  ListBox ListSurface(int height){return new ListBox{MinHeight=Math.Max(100,height),MaxHeight=Math.Max(160,height+80),Background=PanelBrush,Foreground=Ink,BorderThickness=new Thickness(0),HorizontalContentAlignment=HorizontalAlignment.Stretch,FontSize=13,Padding=new Thickness(0),Margin=new Thickness(0,0,0,6)};}
  FrameworkElement CheckedItems(Forms.CheckedListBox source){var stack=new StackPanel();var empty=Text("No items yet. Run a scan or refresh to populate this list.",13,Muted);var view=new ScrollViewer{Content=stack,MinHeight=100,MaxHeight=320,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};string key=null;var checks=new List<CheckBox>();updates.Add(delegate{string next=string.Join("\n",source.Items.Cast<object>().Select(x=>x.ToString()));if(key!=next){key=next;checks.Clear();stack.Children.Clear();for(int i=0;i<source.Items.Count;i++){int index=i;var check=new CheckBox{Content=new TextBlock{Text=source.Items[i].ToString(),TextWrapping=TextWrapping.Wrap},Foreground=Ink,Padding=new Thickness(10),Margin=new Thickness(0,0,0,4),FontSize=13};check.Checked+=delegate{Write(()=>source.SetItemChecked(index,true));};check.Unchecked+=delegate{Write(()=>source.SetItemChecked(index,false));};checks.Add(check);stack.Children.Add(new Border{Child=check,Background=Raised,CornerRadius=new CornerRadius(8),Margin=new Thickness(0,0,0,4)});}if(checks.Count==0)stack.Children.Add(empty);}for(int i=0;i<checks.Count;i++)checks[i].IsChecked=source.GetItemChecked(i);});return view;}
  sealed class InventoryRow {public Forms.ListViewItem Source {get;set;}public string[] Cells {get;set;}}
  FrameworkElement Inventory(Forms.ListView source){var nativeHandle=source.Handle;var view=new ListView{MinHeight=Math.Max(100,source.Height),MaxHeight=Math.Max(160,source.Height+80),Background=PanelBrush,Foreground=Ink,BorderThickness=new Thickness(0),FontSize=13};var gridView=new GridView();for(int i=0;i<source.Columns.Count;i++){int column=i;var factory=new FrameworkElementFactory(typeof(TextBlock));factory.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Cells["+column+"]"));factory.SetValue(TextBlock.ForegroundProperty,Ink);factory.SetValue(TextBlock.MarginProperty,new Thickness(4,8,4,8));factory.SetValue(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis);gridView.Columns.Add(new GridViewColumn{Header=source.Columns[i].Text,Width=Math.Min(340,source.Columns[i].Width),CellTemplate=new DataTemplate{VisualTree=factory}});}ScrollViewer.SetHorizontalScrollBarVisibility(view,ScrollBarVisibility.Auto);view.View=gridView;var originalWidths=gridView.Columns.Select(x=>x.Width).ToArray();view.SizeChanged+=delegate{double space=Math.Max(1,view.ActualWidth-24);double total=originalWidths.Sum();for(int c=0;c<gridView.Columns.Count;c++)gridView.Columns[c].Width=Math.Max(75,originalWidths[c]*Math.Min(1,space/Math.Max(1,total)));};string key=null;InventoryRow[] rows=new InventoryRow[0];view.SelectionChanged+=delegate{Write(delegate{foreach(Forms.ListViewItem item in source.Items)item.Selected=false;var selected=view.SelectedItem as InventoryRow;if(selected!=null){selected.Source.Selected=true;selected.Source.Focused=true;}});};updates.Add(delegate{string next=string.Join("\n",source.Items.Cast<Forms.ListViewItem>().Select(x=>string.Join("\t",x.SubItems.Cast<Forms.ListViewItem.ListViewSubItem>().Select(s=>s.Text))));if(key!=next||rows.Length!=source.Items.Count||rows.Where((x,i)=>x.Source!=source.Items[i]).Any()){key=next;rows=source.Items.Cast<Forms.ListViewItem>().Select(x=>new InventoryRow{Source=x,Cells=x.SubItems.Cast<Forms.ListViewItem.ListViewSubItem>().Select(s=>s.Text).ToArray()}).ToArray();view.ItemsSource=rows;}view.SelectedItem=rows.FirstOrDefault(x=>x.Source.Selected);});return view;}
  FrameworkElement Plot(FrameChart source){var panel=new StackPanel();panel.Children.Add(Text("Frame time · ms",17,Ink));panel.Children.Add(Text("Baseline: blue   •   Tuned: copper   •   Lower is better",12,Muted));var canvas=new Canvas{Height=180,ClipToBounds=true};panel.Children.Add(canvas);FrameStats a=null,b=null;Action draw=delegate{canvas.Children.Clear();double width=canvas.ActualWidth;if(width<=0)return;if(source.A==null&&source.B==null){canvas.Children.Add(Text("Load baseline and tuned captures to compare frame times.",13,Muted));return;}double max=Math.Max(source.A==null?0:source.A.Frames.Max(),source.B==null?0:source.B.Frames.Max());if(max<=0)return;foreach(var capture in new[]{source.A,source.B}){if(capture==null)continue;int count=Math.Min(500,capture.Count);if(count<2)continue;var points=new PointCollection();for(int i=0;i<count;i++){int start=i*capture.Count/count,end=(i+1)*capture.Count/count;double peak=0;for(int j=start;j<end;j++)peak=Math.Max(peak,capture.Frames[j]);points.Add(new Point(i*width/(count-1),160-peak/max*140));}canvas.Children.Add(new Polyline{Points=points,Stroke=capture==source.A?ToolPages.Tone("#4C8DF6"):Accent,StrokeThickness=1.5});}};canvas.SizeChanged+=delegate{draw();};updates.Add(delegate{if(a!=source.A||b!=source.B){a=source.A;b=source.B;draw();}});return panel;}
 }
 static class ToolBrushExtensions {public static Color Color(this Brush brush){return ((SolidColorBrush)brush).Color;}}
}
